package com.example.examplemod.cargo.center;

import com.example.examplemod.cargo.*;
import com.example.examplemod.economy.EconomyManager;
import com.simibubi.create.content.trains.RailwaySavedData;
import com.simibubi.create.content.trains.entity.Train;
import com.simibubi.create.content.trains.graph.DiscoveredPath;
import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.saveddata.SavedData;
import java.util.*;

/** Opt-in world-wide physical fleet. Existing line-bound charter jobs remain owned by CargoCharters. */
public final class PublicFleetRegistry extends SavedData {
    public record Service(UUID train,OwnerRef owner,UUID home,String name,long rate,long dispatchFee,boolean enabled){public Service{if(rate<0||dispatchFee<0||rate>1_000_000_000L||dispatchFee>1_000_000_000L)throw new IllegalArgumentException("fleet_tariff_invalid");}}
    private final Map<UUID,Service> services=new LinkedHashMap<>();
    private final Map<UUID,CompoundTag> jobs=new LinkedHashMap<>();
    private final Set<UUID> completed=new HashSet<>(),pendingRefunds=new HashSet<>();
    private CompoundTag unavailable;private RuntimeException loadFailure;
    public static PublicFleetRegistry get(MinecraftServer s){if(!s.isSameThread())throw new IllegalStateException("Server thread");var data=s.overworld().getDataStorage().computeIfAbsent(new Factory<>(PublicFleetRegistry::new,PublicFleetRegistry::loadGuarded,null),"ccec_public_fleet");if(data.loadFailure!=null)throw new IllegalStateException("Fleet save unavailable; original retained",data.loadFailure);return data;}
    public List<Service> services(){return List.copyOf(services.values());}
    public Optional<Service> service(UUID train){return Optional.ofNullable(services.get(train));}
    public void publish(ServerPlayer actor,UUID id,OwnerRef owner,UUID home,long rate,long dispatch){
        var s=actor.getServer();var train=RailwaySavedData.load(s).getTrains().get(id);var registration=CargoTrainRegistry.find(s,id).orElse(null);
        if(train==null||!owner.manages(s,actor.getUUID())||CargoRailConnections.station(s,home)==null)throw new IllegalArgumentException("fleet_permission");
        if(registration==null){if(!actor.getUUID().equals(train.owner)||!CargoTrainRegistry.register(s,actor.getUUID(),id,CargoTrainRegistry.AccessMode.PUBLIC))throw new IllegalArgumentException("fleet_permission");registration=CargoTrainRegistry.find(s,id).orElseThrow();}
        if(!CargoOwners.get(s).owner("train/"+id,registration.ownerId()).manages(s,actor.getUUID())||hasJob(id)||CargoShipmentRegistry.get(s).inUse("train",id))throw new IllegalArgumentException("shipment_in_use");
        if(!CargoOwners.get(s).change(s,actor.getUUID(),"train/"+id,registration.ownerId(),registration.accessMode(),new CargoOwners.Access(owner,CargoTrainRegistry.AccessMode.PUBLIC,Set.of(),Set.of())))throw new IllegalArgumentException("fleet_permission");
        services.put(id,new Service(id,owner,home,train.name.getString(),rate,dispatch,true));setDirty();
    }
    public void disable(ServerPlayer actor,UUID id){var old=services.get(id);var registration=CargoTrainRegistry.find(actor.getServer(),id).orElse(null);if(old==null||!(registration==null?old.owner():CargoOwners.get(actor.getServer()).owner("train/"+id,registration.ownerId())).manages(actor.getServer(),actor.getUUID()))throw new IllegalArgumentException("fleet_permission");services.put(id,new Service(id,old.owner(),old.home(),old.name(),old.rate(),old.dispatchFee(),false));setDirty();}
    public boolean hasJob(UUID id){var j=jobs.get(id);return j!=null&&!j.getString("Phase").equals("DONE");}
    public Optional<UUID> shipment(UUID train){var job=jobs.get(train);return job==null||job.getString("Phase").equals("DONE")?Optional.empty():Optional.of(job.getUUID("Shipment"));}
    public String state(MinecraftServer s,Service service){if(hasJob(service.train()))return "BUSY";if(!service.enabled())return "DISABLED";if(!RailwaySavedData.load(s).getTrains().containsKey(service.train()))return "MISSING";var registration=CargoTrainRegistry.find(s,service.train()).orElse(null);if(registration==null||!CargoOwners.get(s).owner("train/"+service.train(),registration.ownerId()).equals(service.owner()))return "OWNERSHIP_CHANGED";return ready(s,service)?"AVAILABLE":"NOT_READY";}
    public boolean locks(MinecraftServer s,String kind,UUID id){for(var job:jobs.values())if(!job.getString("Phase").equals("DONE")){var shipment=CargoShipmentRegistry.get(s).find(job.getUUID("Shipment")).orElse(null);if(shipment!=null&&ShipmentLocks.blocks(CargoShipmentRegistry.Stage.REQUESTED,kind,id,new ShipmentLocks.References(shipment.sourceWarehouse(),shipment.destinationWarehouse(),shipment.source(),shipment.finalPoint(),shipment.route())))return true;}return false;}
    private boolean ready(MinecraftServer s,Service service){return ready(s,service,null);}
    private boolean ready(MinecraftServer s,Service service,UUID ignoreShipment){var t=RailwaySavedData.load(s).getTrains().get(service.train());var old=jobs.get(service.train());
        boolean occupied=CargoShipmentRegistry.get(s).all().stream().anyMatch(sh->!sh.id().equals(ignoreShipment)&&sh.stage()!=CargoShipmentRegistry.Stage.COMPLETED&&sh.stage()!=CargoShipmentRegistry.Stage.CANCELLED&&sh.route().stream().anyMatch(leg->leg.train().equals(service.train())));
        var registration=CargoTrainRegistry.find(s,service.train()).orElse(null);boolean owner=registration!=null&&CargoOwners.get(s).owner("train/"+service.train(),registration.ownerId()).equals(service.owner());
        return owner&&(service.enabled()||ignoreShipment!=null)&&t!=null&&!t.invalid&&!t.derailed&&!t.manualTick&&Math.abs(t.speed)<.001&&t.graph!=null&&t.getCurrentStation()!=null&&!hasJob(t.id)&&!occupied&&CargoPackageAssignment.mayAssignTrain(s,service.owner(),t.id)&&(t.hasForwardConductor()||t.doubleEnded&&t.hasBackwardConductor())&&(t.runtime.getSchedule()==null||old!=null&&owned(s,t,old));
    }
    public static List<UUID> stationsFor(MinecraftServer s,UUID point){return CargoLineRegistry.get(s).stations().entrySet().stream().filter(e->e.getValue().equals(point)&&CargoRoutePlanner.equipment(s,point,e.getKey())).map(Map.Entry::getKey).sorted().toList();}
    private static int packageSlots(Train train){int slots=0;for(var carriage:train.carriages){var inv=carriage.storage.getAllItems();if(inv==null)continue;for(int i=0;i<inv.getSlots();i++)if(inv.getStackInSlot(i).isEmpty()&&inv.getSlotLimit(i)>0)slots++;}return slots;}
    public Optional<CargoRoutePlanner.Route> plan(MinecraftServer s,OwnerRef payer,UUID from,UUID to,int quantity,ItemStack item,String preference){
        var book=EconomyManager.get(s.overworld()).roadTolls();CargoRoutePlanner.Route winner=null;double best=Double.POSITIVE_INFINITY;int[] work={1_000_000};
        try{for(var service:services.values())if(ready(s,service)){var train=RailwaySavedData.load(s).getTrains().get(service.train());int slots=packageSlots(train);if(slots<1)continue;
            int capacity=Math.max(1,Math.min(4096,slots*9*(item==null||item.isEmpty()?64:item.getMaxStackSize())));int cycles=Math.max(1,(quantity+capacity-1)/capacity);if(cycles>32)continue;
            for(UUID source:stationsFor(s,from))for(UUID destination:stationsFor(s,to)){
                var approach=RailRoutes.journey(s,train,RailRoutes.pose(train),source,payer,preference,service.rate(),work).orElse(null);if(approach==null)continue;
                var phases=new CompoundTag();var fares=new CompoundTag();putPhase(phases,"APPROACH",approach.path(),approach.meter(),book);long approachFare=service.owner().equals(payer)?0:Math.addExact(service.dispatchFee(),RailTollBook.ceiling(RailTollBook.units(approach.path().distance(),service.rate())));fares.putLong("APPROACH",approachFare);double distance=approach.path().distance();var pose=approach.arrival();boolean possible=true;
                for(int i=0;i<cycles;i++){
                    var delivery=RailRoutes.journey(s,train,pose,destination,payer,preference,service.rate(),work).orElse(null);if(delivery==null){possible=false;break;}putPhase(phases,"DELIVERY"+i,delivery.path(),delivery.meter(),book);fares.putLong("DELIVERY"+i,service.owner().equals(payer)?0:RailTollBook.ceiling(RailTollBook.units(delivery.path().distance(),service.rate())));distance+=delivery.path().distance();pose=delivery.arrival();
                    if(i<cycles-1){var back=RailRoutes.journey(s,train,pose,source,payer,preference,service.rate(),work).orElse(null);if(back==null){possible=false;break;}putPhase(phases,"REPOSITION"+i,back.path(),back.meter(),book);fares.putLong("REPOSITION"+i,service.owner().equals(payer)?0:RailTollBook.ceiling(RailTollBook.units(back.path().distance(),service.rate())));distance+=back.path().distance();pose=back.arrival();}
                }
                if(!possible)continue;var home=RailRoutes.journey(s,train,pose,service.home(),payer,preference,service.rate(),work).orElse(null);if(home==null)continue;putPhase(phases,"RETURN",home.path(),home.meter(),book);fares.putLong("RETURN",service.owner().equals(payer)?0:RailTollBook.ceiling(RailTollBook.units(home.path().distance(),service.rate())));distance+=home.path().distance();
                var trip=new CompoundTag();trip.putBoolean("Fleet",true);trip.putUUID("Train",train.id);trip.put("Carrier",service.owner().save());trip.putUUID("SourceStation",source);trip.putUUID("DestinationStation",destination);trip.putUUID("HomeStation",service.home());trip.putInt("Cycles",cycles);trip.putInt("Capacity",capacity);trip.putString("Preference",preference);
                trip.put("Phases",phases);trip.put("CarrierPhases",fares);long carrier=0;for(String key:fares.getAllKeys())carrier=Math.addExact(carrier,fares.getLong(key));long tolls=0;for(String key:phases.getAllKeys())tolls=Math.addExact(tolls,book.estimate(RailRoutes.Path.load(phases.getCompound(key).getCompound("MeterPath")).spans(),payer));long price=Math.addExact(carrier,tolls);
                trip.putDouble("Distance",distance);trip.putLong("CarrierCost",carrier);trip.putLong("Tolls",tolls);trip.putLong("EtaSeconds",Math.max(1,(long)Math.ceil(distance/Math.max(.1,train.maxSpeed())/20)+60L*cycles));double objective=preference.equals("FASTEST")?trip.getLong("EtaSeconds"):price;
                if(winner==null||objective<best||objective==best&&distance<winner.trip().getDouble("Distance")){best=objective;winner=new CargoRoutePlanner.Route(List.of(new CargoRoutePlanner.Leg(train.id,from,to,train.id,carrier)),price,trip);}
            }
        }}catch(IllegalArgumentException limit){if(!"fleet_route_too_complex".equals(limit.getMessage())||winner==null)throw limit;var trip=winner.trip();trip.putBoolean("SearchLimited",true);return Optional.of(new CargoRoutePlanner.Route(winner.legs(),winner.price(),trip));}return Optional.ofNullable(winner);
    }
    private static void putPhase(CompoundTag phases,String phase,RailRoutes.Path path,RailTollBook book){putPhase(phases,phase,path,path,book);}
    private static void putPhase(CompoundTag phases,String phase,RailRoutes.Path path,RailRoutes.Path meter,RailTollBook book){var t=new CompoundTag();t.put("Path",path.save());t.put("MeterPath",meter.save());var fees=new ListTag();for(int i=0;i<meter.segments().size();i++)for(var c:book.charges(meter.segments().get(i).span())){var v=new CompoundTag();v.putInt("Segment",i);v.putUUID("Road",c.road());v.put("Creditor",c.creditor().save());v.putLong("Revision",c.revision());v.putLong("Rate",c.rate());v.put("Span",c.span().save());fees.add(v);}t.put("Charges",fees);phases.put(phase,t);}
    public void prepare(MinecraftServer s,CargoShipmentRegistry.Shipment shipment){var trip=shipment.trip();if(!trip.getBoolean("Fleet"))return;UUID train=trip.getUUID("Train");var old=jobs.get(train);if(old!=null&&old.getUUID("Shipment").equals(shipment.id()))return;var service=services.get(train);if(service==null||!ready(s,service,shipment.id())||!service.owner().equals(OwnerRef.load(trip.getCompound("Carrier"))))throw new IllegalArgumentException("charter_busy");
        for(String phase:trip.getCompound("Phases").getAllKeys()){var data=trip.getCompound("Phases").getCompound(phase);if(!RailRoutes.valid(s,RailRoutes.Path.load(data.getCompound("Path")))||data.contains("MeterPath")&&!RailRoutes.valid(s,RailRoutes.Path.load(data.getCompound("MeterPath"))))throw new IllegalArgumentException("delivery_quote_changed");}
        var job=new CompoundTag();job.putUUID("Shipment",shipment.id());job.put("Trip",trip);var physical=RailwaySavedData.load(s).getTrains().get(train);if(physical!=null&&physical.getCurrentStation()!=null)job.putUUID("OriginStation",physical.getCurrentStation().id);job.putString("Phase","APPROACH");job.putInt("Cycle",0);job.putInt("Segment",0);if(old!=null&&old.contains("Schedule"))job.put("Schedule",old.getCompound("Schedule").copy());jobs.put(train,job);setDirty();
    }
    private static boolean owned(MinecraftServer s,Train train,CompoundTag job){return train.runtime.getSchedule()!=null&&job.contains("Schedule")&&CargoSchedulePlan.shape(train.runtime.getSchedule().write(s.registryAccess())).equals(job.getCompound("Schedule"));}
    private static boolean authority(MinecraftServer s,Train train,CompoundTag job){var registration=CargoTrainRegistry.find(s,train.id).orElse(null);var owner=OwnerRef.load(job.getCompound("Trip").getCompound("Carrier"));return registration!=null&&CargoOwners.get(s).owner("train/"+train.id,registration.ownerId()).equals(owner)&&CargoPackageAssignment.mayAssignTrain(s,owner,train.id);}
    private static String pathPhase(CompoundTag job){String phase=job.getString("Phase");return phase.equals("LOADING")?"APPROACH":phase.equals("UNLOADING")?"DELIVERY"+job.getInt("Cycle"):phase.equals("DELIVERY")||phase.equals("REPOSITION")?phase+job.getInt("Cycle"):phase;}
    private static RailRoutes.Path path(CompoundTag job){return RailRoutes.Path.load(job.getCompound("Trip").getCompound("Phases").getCompound(pathPhase(job)).getCompound("Path"));}
    public DiscoveredPath navigation(MinecraftServer s,Train train){var job=jobs.get(train.id);if(job==null||job.getString("Phase").equals("DONE")||train.manualTick||!owned(s,train,job)||!authority(s,train,job))return null;try{return RailRoutes.nativePath(s,train,EconomyManager.get(s.overworld()).roadTolls().headPath(job.getUUID("Shipment"),pathPhase(job)).orElseGet(()->path(job)));}catch(RuntimeException invalid){job.putString("Problem","rail_route_changed");setDirty();return null;}}
    public com.simibubi.create.content.trains.entity.TravellingPoint proofHead(Train train){var job=jobs.get(train.id);if(job==null||job.getString("Phase").equals("DONE")||job.getString("Phase").equals("LOADING")||train.carriages.isEmpty())return null;return path(job).backwards()?train.carriages.getLast().getTrailingPoint():train.carriages.getFirst().getLeadingPoint();}
    private void anchorHead(MinecraftServer s,Train train,CompoundTag job){String phase=pathPhase(job);var data=job.getCompound("Trip").getCompound("Phases").getCompound(phase);var book=EconomyManager.get(s.overworld()).roadTolls();if(data.getBoolean("OperatorCost")||book.headPath(job.getUUID("Shipment"),phase).isPresent())return;var approved=path(job);var station=train.getCurrentStation();UUID expected=phase.equals("APPROACH")?job.hasUUID("OriginStation")?job.getUUID("OriginStation"):null:phase.startsWith("DELIVERY")?job.getCompound("Trip").getUUID("SourceStation"):job.getCompound("Trip").getUUID("DestinationStation");if(station==null||expected!=null&&!station.id.equals(expected))throw new IllegalArgumentException("fleet_phase_start_changed");
        if(approved.segments().isEmpty()){if(!station.id.equals(approved.destination()))throw new IllegalArgumentException("fleet_phase_start_changed");book.anchorHead(job.getUUID("Shipment"),phase,approved);return;}var point=approved.backwards()?train.carriages.getLast().getTrailingPoint():train.carriages.getFirst().getLeadingPoint();var a=approved.backwards()?point.node2:point.node1;var b=approved.backwards()?point.node1:point.node2;var first=approved.segments().getFirst();if(!first.a().equals(RailRoutes.Node.of(a))||!first.b().equals(RailRoutes.Node.of(b)))throw new IllegalArgumentException("fleet_phase_start_changed");var edge=train.graph.getConnectionsFrom(a).get(b);double from=approved.backwards()?edge.getLength()-point.position:point.position;if(from<0||from>first.to())throw new IllegalArgumentException("fleet_phase_start_changed");var span=RailGeometry.span(train.graph,edge,from,first.to());var segments=new ArrayList<>(approved.segments());segments.set(0,new RailRoutes.Segment(first.a(),first.b(),from,first.to(),span));double distance=approved.distance()-(first.span().to()-first.span().from())+span.to()-span.from();book.anchorHead(job.getUUID("Shipment"),phase,new RailRoutes.Path(approved.destination(),approved.backwards(),segments,distance));
    }
    public void observeHead(MinecraftServer s,Train train,RailRoutes.Node a,RailRoutes.Node b,double from,double to,RailGeometry.Span actual){var job=jobs.get(train.id);if(job==null||train.manualTick||!authority(s,train,job)||!owned(s,train,job)||job.getString("Phase").equals("DONE")||job.getString("Phase").equals("LOADING"))return;String phase=pathPhase(job);if(job.getCompound("Trip").getCompound("Phases").getCompound(phase).getBoolean("OperatorCost"))return;var book=EconomyManager.get(s.overworld()).roadTolls();var approved=book.headPath(job.getUUID("Shipment"),phase).orElse(null);if(approved==null)return;var movementA=to>=from?a:b;var movementB=to>=from?b:a;for(int i=book.headCursor(job.getUUID("Shipment"),phase);i<approved.segments().size();i++){var segment=approved.segments().get(i);if(segment.a().equals(movementA)&&segment.b().equals(movementB)&&segment.span().overlap(actual)>=actual.to()-actual.from()-.00001){book.headTravel(job.getUUID("Shipment"),phase,i,actual);return;}}}
    public boolean prepared(MinecraftServer s,CargoShipmentRegistry.Shipment shipment){var job=jobs.get(shipment.trip().getUUID("Train"));var train=job==null?null:RailwaySavedData.load(s).getTrains().get(shipment.trip().getUUID("Train"));return job!=null&&train!=null&&job.getString("Problem").isBlank()&&job.getUUID("Shipment").equals(shipment.id())&&owned(s,train,job);}
    public boolean complete(UUID shipment){return completed.contains(shipment)||jobs.values().stream().anyMatch(j->j.getUUID("Shipment").equals(shipment)&&j.getString("Phase").equals("DONE"));}
    public String progress(UUID shipment){return jobs.values().stream().filter(j->j.getUUID("Shipment").equals(shipment)).map(j->j.getString("Problem").isBlank()?"CHARTER_"+j.getString("Phase"):j.getString("Problem")).findFirst().orElse("");}
    public String warning(UUID shipment){return jobs.values().stream().filter(j->j.getUUID("Shipment").equals(shipment)).map(j->j.getString("Warning")).findFirst().orElse("");}
    public boolean assigned(UUID shipment,UUID train){var j=jobs.get(train);return j!=null&&!j.getString("Phase").equals("DONE")&&j.getUUID("Shipment").equals(shipment);}
    private void phase(MinecraftServer s,CompoundTag job,String phase){job.putString("Phase",phase);job.putInt("Segment",0);job.remove("Position");job.remove("Problem");if(phase.equals("DONE")){completed.add(job.getUUID("Shipment"));pendingRefunds.add(job.getUUID("Shipment"));}EconomyManager.get(s.overworld()).roadTolls().phase(job.getUUID("Shipment"),pathPhase(job));setDirty();}
    private static void payPhase(MinecraftServer s,CompoundTag job,String phase){var trip=job.getCompound("Trip");if(!trip.contains("CarrierPhases")||!trip.getCompound("CarrierPhases").contains(phase))return;var book=EconomyManager.get(s.overworld()).cargo();var order=book.order(job.getUUID("Shipment")).orElseThrow();if(order.state()==CargoCommerceBook.State.CANCELLED)return;if(!trip.getCompound("Phases").getCompound(phase).getBoolean("OperatorCost")&&!EconomyManager.get(s.overworld()).roadTolls().phaseComplete(order.id(),phase))throw new IllegalArgumentException("fleet_phase_evidence_missing");boolean paid=phase.equals("RETURN")&&job.contains("ReturnFareOverride")?book.payCarrierPhase(order.id(),phase,job.getLong("ReturnFareOverride")):book.payCarrierPhase(order.id(),phase);if(!paid)throw new IllegalArgumentException("fleet_carrier_payment_unavailable");}
    public void tick(MinecraftServer s){var refunds=pendingRefunds.iterator();while(refunds.hasNext())if(EconomyManager.get(s.overworld()).roadTolls().finishTrip(refunds.next())){refunds.remove();setDirty();}for(var entry:jobs.entrySet()){var job=entry.getValue();if(job.getString("Phase").equals("DONE"))continue;var train=RailwaySavedData.load(s).getTrains().get(entry.getKey());var shipment=CargoShipmentRegistry.get(s).find(job.getUUID("Shipment")).orElse(null);if(train==null||shipment==null)continue;
        try{var order=EconomyManager.get(s.overworld()).cargo().order(shipment.id()).orElse(null);if(order==null)continue;
            if(order.state()==CargoCommerceBook.State.REFUNDED){if(owned(s,train,job))train.runtime.paused=true;if(EconomyManager.get(s.overworld()).roadTolls().finishTrip(shipment.id()))phase(s,job,"DONE");continue;}
            if(order.state()==CargoCommerceBook.State.CANCELLED&&!job.getString("Phase").equals("RETURN"))phase(s,job,"RETURN");
            if(order.state()==CargoCommerceBook.State.CANCELLING&&shipment.cancellationResolved()&&!job.getString("Phase").equals("RETURN"))cancelReturn(s,train,job);
            if(train.invalid||train.derailed||train.manualTick||!authority(s,train,job))throw new IllegalArgumentException("charter_not_ready");
            if(order.state()!=CargoCommerceBook.State.CANCELLED&&!(order.state()==CargoCommerceBook.State.CANCELLING&&shipment.cancellationResolved())&&(shipment.stage()==CargoShipmentRegistry.Stage.BLOCKED||shipment.stage()==CargoShipmentRegistry.Stage.FAILED||shipment.cancellationRequested())){if(owned(s,train,job))train.runtime.paused=true;continue;}
            String phase=job.getString("Phase");var route=path(job);var station=CargoRailConnections.station(s,route.destination());if(station==null||!RailRoutes.valid(s,route))throw new IllegalArgumentException("rail_route_changed");
            if(!phase.equals("LOADING"))anchorHead(s,train,job);
            if(train.runtime.getSchedule()!=null&&!owned(s,train,job))throw new IllegalArgumentException("schedule_existing");
            var schedule=CargoSchedules.build(s.registryAccess(),List.of(station.station().name),86400);schedule.cyclic=false;var shape=CargoSchedulePlan.shape(schedule.write(s.registryAccess()));
            if(train.runtime.getSchedule()==null||!job.getCompound("Schedule").equals(shape)){job.put("Schedule",shape);train.runtime.setSchedule(schedule,true);RailwaySavedData.load(s).setDirty();setDirty();}
            boolean arrived=train.getCurrentStation()!=null&&train.getCurrentStation().id.equals(route.destination());train.runtime.paused=arrived;RailwaySavedData.load(s).setDirty();if(!arrived)continue;
            if(phase.equals("APPROACH")||phase.equals("REPOSITION")){payPhase(s,job,pathPhase(job));if(phase.equals("REPOSITION"))job.putInt("Cycle",job.getInt("Cycle")+1);phase(s,job,"LOADING");job.putLong("WaitSince",s.overworld().getGameTime());continue;}
            if(phase.equals("LOADING")){int boarded=shipment.boardedUnits(train.id,job.getCompound("Trip").getUUID("SourceStation"),0),unloaded=shipment.hopUnits(0);if(boarded<=unloaded)continue;
                if(boarded<shipment.quantity()&&packageSlots(train)>0&&s.overworld().getGameTime()-job.getLong("WaitSince")<100)continue;job.putInt("LoadTarget",boarded);phase(s,job,"DELIVERY");continue;}
            if(phase.equals("DELIVERY")){if(shipment.hopUnits(0)<job.getInt("LoadTarget"))continue;payPhase(s,job,pathPhase(job));if(shipment.hopUnits(0)>=shipment.quantity()){phase(s,job,"RETURN");continue;}
                int cycle=job.getInt("Cycle");if(cycle>=job.getCompound("Trip").getInt("Cycles")-1)extraCycle(s,train,job);phase(s,job,"REPOSITION");continue;}
            if(phase.equals("RETURN")){if(job.getCompound("Trip").getCompound("Phases").getCompound("RETURN").getBoolean("OperatorCost")||EconomyManager.get(s.overworld()).roadTolls().phaseComplete(shipment.id(),"RETURN")){completed.add(shipment.id());pendingRefunds.add(shipment.id());setDirty();}payPhase(s,job,"RETURN");if(EconomyManager.get(s.overworld()).roadTolls().finishTrip(shipment.id()))phase(s,job,"DONE");else{job.putString("Problem","rail_payout_wait");setDirty();}}
        }catch(RuntimeException failure){job.putString("Problem",Objects.toString(failure.getMessage(),"charter_dispatch_blocked"));if(owned(s,train,job))train.runtime.paused=true;setDirty();}
    }}
    private void cancelReturn(MinecraftServer s,Train train,CompoundTag job){var trip=job.getCompound("Trip");var phases=trip.getCompound("Phases");var original=RailRoutes.Path.load(phases.getCompound("RETURN").getCompound("Path"));var owner=OwnerRef.load(trip.getCompound("Carrier"));var actual=RailRoutes.journey(s,train,RailRoutes.pose(train),trip.getUUID("HomeStation"),owner,"FASTEST",0,new int[]{1_000_000}).orElseThrow(()->new IllegalArgumentException("fleet_return_unavailable"));long cap=trip.getCompound("CarrierPhases").getLong("RETURN");long fare=actual.path().distance()<=0?0:original.distance()<=0?cap:Math.min(cap,java.math.BigDecimal.valueOf(cap).multiply(java.math.BigDecimal.valueOf(actual.path().distance())).divide(java.math.BigDecimal.valueOf(original.distance()),0,java.math.RoundingMode.DOWN).longValueExact());job.putLong("ReturnFareOverride",fare);
        if(!original.equals(actual.path())||!phases.getCompound("RETURN").getCompound("MeterPath").equals(actual.meter().save())){putPhase(phases,"RETURN",actual.path(),actual.meter(),EconomyManager.get(s.overworld()).roadTolls());phases.getCompound("RETURN").putBoolean("OperatorCost",true);trip.put("Phases",phases);job.put("Trip",trip);job.putString("Warning","fleet_cancelled_return_operator_cost");}phase(s,job,"RETURN");
    }
    /** Native packagers may split into partly filled boxes. The carrier, never the customer, funds extra cycles. */
    private void extraCycle(MinecraftServer s,Train train,CompoundTag job){int cycle=job.getInt("Cycle");if(cycle>=63)throw new IllegalArgumentException("fleet_more_cycles_required");var trip=job.getCompound("Trip");var owner=OwnerRef.load(trip.getCompound("Carrier"));int[] work={1_000_000};
        var back=RailRoutes.journey(s,train,RailRoutes.pose(train),trip.getUUID("SourceStation"),owner,"FASTEST",0,work).orElseThrow(()->new IllegalArgumentException("fleet_return_unavailable"));var delivery=RailRoutes.journey(s,train,back.arrival(),trip.getUUID("DestinationStation"),owner,"FASTEST",0,work).orElseThrow(()->new IllegalArgumentException("fleet_return_unavailable"));var home=RailRoutes.journey(s,train,delivery.arrival(),trip.getUUID("HomeStation"),owner,"FASTEST",0,work).orElseThrow(()->new IllegalArgumentException("fleet_return_unavailable"));
        var phases=trip.getCompound("Phases");var book=EconomyManager.get(s.overworld()).roadTolls();putPhase(phases,"REPOSITION"+cycle,back.path(),back.meter(),book);phases.getCompound("REPOSITION"+cycle).putBoolean("OperatorCost",true);putPhase(phases,"DELIVERY"+(cycle+1),delivery.path(),delivery.meter(),book);phases.getCompound("DELIVERY"+(cycle+1)).putBoolean("OperatorCost",true);
        var oldReturn=phases.getCompound("RETURN");if(!oldReturn.getCompound("Path").equals(home.path().save())||!oldReturn.getCompound("MeterPath").equals(home.meter().save())){putPhase(phases,"RETURN",home.path(),home.meter(),book);phases.getCompound("RETURN").putBoolean("OperatorCost",true);}trip.put("Phases",phases);trip.putInt("Cycles",cycle+2);job.put("Trip",trip);job.putString("Warning","fleet_extra_cycles_operator_cost");setDirty();}
    public CompoundTag currentTrip(UUID shipment){for(var job:jobs.values())if(job.getUUID("Shipment").equals(shipment))return job.getCompound("Trip").copy();return new CompoundTag();}
    /** Checks directed, monotonically consumed physical intervals before using customer escrow. */
    public boolean bill(MinecraftServer s,Train train,UUID receipt,RailRoutes.Node a,RailRoutes.Node b,double from,double to,RailGeometry.Span actual){
        var job=jobs.get(train.id);if(job==null||job.getString("Phase").equals("DONE")||train.manualTick||!authority(s,train,job))return false;String phase=pathPhase(job);var phaseData=job.getCompound("Trip").getCompound("Phases").getCompound(phase);if(phaseData.getBoolean("OperatorCost"))return false;var path=RailRoutes.Path.load(phaseData.getCompound(phaseData.contains("MeterPath")?"MeterPath":"Path"));
        RailRoutes.Node movementA=to>=from?a:b,movementB=to>=from?b:a;int start=job.getInt("Segment");
        for(int i=start;i<path.segments().size();i++){var segment=path.segments().get(i);if(!segment.a().equals(movementA)||!segment.b().equals(movementB))continue;if(segment.span().overlap(actual)<actual.to()-actual.from()-.02)return false;
            var nodeA=a.resolve(train.graph);var nodeB=b.resolve(train.graph);var edge=nodeA==null||nodeB==null?null:train.graph.getConnectionsFrom(nodeA).get(nodeB);if(edge==null)return false;
            var charges=new ArrayList<RailTollBook.Charge>();for(var raw:phaseData.getList("Charges",10)){var t=(CompoundTag)raw;if(t.getInt("Segment")==i)charges.add(new RailTollBook.Charge(t.getUUID("Road"),OwnerRef.load(t.getCompound("Creditor")),t.getLong("Revision"),t.getLong("Rate"),RailGeometry.Span.load(t.getCompound("Span"))));}
            var tolls=EconomyManager.get(s.overworld()).roadTolls();var previous=tolls.consumed(job.getUUID("Shipment"),phase,i).orElse(null);if(!tolls.tripTravel(receipt,job.getUUID("Shipment"),phase,i,actual,charges))return false;if(previous!=null&&previous.overlap(actual)>.00001){var repeat=new RailGeometry.Span(actual.shape(),Math.max(actual.from(),previous.from()),Math.min(actual.to(),previous.to()));var owner=OwnerRef.load(job.getCompound("Trip").getCompound("Carrier"));tolls.travel(RailTollBook.component(receipt,"operator_repeat"),owner,tolls.passage(train.id,tolls.charges(repeat)));}job.putInt("Segment",i);job.putDouble("Position",to>=from?to:edge.getLength()-to);setDirty();return true;
        }return false;
    }
    public static CompoundTag map(MinecraftServer s,CompoundTag trip){var result=new CompoundTag();var rails=new ListTag();var phases=trip.getCompound("Phases");for(String key:new TreeSet<>(phases.getAllKeys()))for(var rail:RailRoutes.geometry(s,RailRoutes.Path.load(phases.getCompound(key).getCompound(phases.getCompound(key).contains("MeterPath")?"MeterPath":"Path")),key)){if(rails.size()<4096)rails.add(rail);}result.put("Rails",rails);result.putBoolean("RouteFound",true);result.put("Markers",new ListTag());return result;}
    private static PublicFleetRegistry loadGuarded(CompoundTag t,HolderLookup.Provider p){try{return load(t,p);}catch(RuntimeException e){var d=new PublicFleetRegistry();d.unavailable=t.copy();d.loadFailure=e;return d;}}
    public static PublicFleetRegistry load(CompoundTag root,HolderLookup.Provider p){if(root.getInt("Version")!=1)throw new IllegalArgumentException("Fleet version");var data=new PublicFleetRegistry();for(var raw:root.getList("Services",10)){var t=(CompoundTag)raw;var v=new Service(t.getUUID("Train"),OwnerRef.load(t.getCompound("Owner")),t.getUUID("Home"),t.getString("Name"),t.getLong("Rate"),t.getLong("Dispatch"),t.getBoolean("Enabled"));if(data.services.putIfAbsent(v.train(),v)!=null)throw new IllegalArgumentException("Duplicate fleet train");}for(var raw:root.getList("Jobs",10)){var t=((CompoundTag)raw).copy();if(!t.hasUUID("Train")||!t.hasUUID("Shipment")||!Set.of("APPROACH","LOADING","DELIVERY","REPOSITION","RETURN","DONE").contains(t.getString("Phase"))||data.jobs.putIfAbsent(t.getUUID("Train"),t)!=null)throw new IllegalArgumentException("Invalid fleet job");}for(var raw:root.getList("Completed",11))data.completed.add(NbtUtils.loadUUID(raw));for(var job:data.jobs.values())if(job.getString("Phase").equals("DONE"))data.completed.add(job.getUUID("Shipment"));data.pendingRefunds.addAll(data.completed);return data;}
    @Override public CompoundTag save(CompoundTag root,HolderLookup.Provider p){if(unavailable!=null)return unavailable.copy();root.putInt("Version",1);var list=new ListTag();for(var v:services.values()){var t=new CompoundTag();t.putUUID("Train",v.train());t.put("Owner",v.owner().save());t.putUUID("Home",v.home());t.putString("Name",v.name());t.putLong("Rate",v.rate());t.putLong("Dispatch",v.dispatchFee());t.putBoolean("Enabled",v.enabled());list.add(t);}root.put("Services",list);var js=new ListTag();jobs.forEach((train,job)->{var t=job.copy();t.putUUID("Train",train);js.add(t);});root.put("Jobs",js);var done=new ListTag();completed.stream().sorted().forEach(id->done.add(NbtUtils.createUUID(id)));root.put("Completed",done);return root;}
}
